export function factoryDailyMaterialBalancesV2029(mb:MultiBusinessEnterpriseStateV2023,factoryId:string,date:string){const factory=mb.factories.find(x=>x.id===factoryId);if(!factory)return [];const warehouseIds=[factory.raw_material_warehouse_id,factory.finished_goods_warehouse_id].filter(Boolean) as string[];return mb.products.map(product=>{const moves=mb.inventory_movements.filter(m=>warehouseIds.includes(m.warehouse_id)&&m.product_id===product.id);const before=moves.filter(m=>m.occurred_at.slice(0,10)<date);const day=moves.filter(m=>m.occurred_at.slice(0,10)===date);const signed=(m:(typeof moves)[number])=>['receipt','transfer_in','adjustment_in','return_in'].includes(m.kind)?m.quantity_base:['issue','transfer_out','adjustment_out','return_out'].includes(m.kind)?-m.quantity_base:0;const opening=before.reduce((s,m)=>s+signed(m),0),incoming=day.filter(m=>signed(m)>0).reduce((s,m)=>s+signed(m),0),used=-day.filter(m=>signed(m)<0).reduce((s,m)=>s+signed(m),0);return {product_id:product.id,product_name:product.name,opening,incoming,used,remaining:opening+incoming-used,unit:product.base_unit};}).filter(x=>x.opening||x.incoming||x.used||x.remaining);}

