export function factoryWorkforceSummaryV2029(workforce:WorkforcePayrollStateV2025,factoryBusinessUnitId?:string){const profiles=workforce.profiles.filter(x=>!factoryBusinessUnitId||x.home_business_unit_id===factoryBusinessUnitId||workforce.assignments.some(a=>a.employee_id===x.employee_id&&a.business_unit_id===factoryBusinessUnitId&&a.active));const ids=new Set(profiles.map(x=>x.employee_id));return {people:profiles.length,workers:profiles.filter(x=>x.job_family==='factory_worker'||x.job_family==='worker').length,supervisors:profiles.filter(x=>x.job_family==='production_supervisor').length,doctors:profiles.filter(x=>x.job_family==='veterinarian'||x.job_family==='consultant').length,payroll_lines:workforce.payroll_lines.filter(x=>ids.has(x.employee_id)).length,advances:workforce.advances.filter(x=>ids.has(x.employee_id)).length,leave_requests:workforce.leave_requests.filter(x=>ids.has(x.employee_id)).length};}

export function factoryCompletionScoreV2029(state:FeedFactoryCompletionStateV2029){const implemented=FACTORY_SECTIONS_V2029.filter(x=>x.completion>=90);return {sections:FACTORY_SECTIONS_V2029.length,implemented:implemented.length,score:Math.round(implemented.reduce((s,x)=>s+x.completion,0)/FACTORY_SECTIONS_V2029.length),passed:implemented.length===15};}

export function validateFactoryCompletionV2029(state:FeedFactoryCompletionStateV2029,mb:MultiBusinessEnterpriseStateV2023,web:EnterpriseWebStateV202,workforce?:WorkforcePayrollStateV2025){const issues:string[]=[];const ext=state.factory_completion_v20_2_9;const unique=(rows:string[],label:string)=>{const seen=new Set<string>();for(const x of rows){if(seen.has(x))issues.push(`${label}_duplicate:${x}`);seen.add(x)}};unique(ext.supplier_relationships.map(x=>x.id),'supplier_relationship');unique(ext.receiving_controls.map(x=>x.id),'receiving_control');unique(ext.sales_orders.map(x=>x.id),'sales_order');unique(ext.sales_dispatches.map(x=>x.id),'sales_dispatch');unique(ext.sales_invoices.map(x=>x.id),'factory_sales_invoice');unique(ext.customer_receipts.map(x=>x.id),'factory_customer_receipt');unique(ext.sales_returns.map(x=>x.id),'factory_sales_return');unique(ext.sales_credit_notes.map(x=>x.id),'factory_sales_credit_note');unique(ext.report_executions.map(x=>x.id),'report_execution');for(const x of ext.material_staging)if(x.transfer_reference_id&&x.note?.toLowerCase().includes('consumption'))issues.push(`staging_consumption_semantic_violation:${x.id}`);for(const x of ext.receiving_controls){const sum=decimalAddV2029(decimalAddV2029(x.accepted_qty,x.quarantine_qty),decimalAddV2029(x.rejected_qty,x.damaged_qty));if(decimalCmpV2029(sum,x.received_qty)>0)issues.push(`receiving_disposition_overflow:${x.id}`);}for(const x of ext.customer_credit_profiles)if(!ext.customer_relationships.some(r=>r.id===x.relationship_id))issues.push(`credit_profile_orphan_relationship:${x.id}`);for(const x of ext.transport_rates)if(!ext.transport_zones.some(z=>z.id===x.zone_id))issues.push(`transport_rate_orphan_zone:${x.id}`);for(const x of ext.production_actuals)if(!state.manufacturing_orders.some(o=>o.id===x.work_order_id))issues.push(`production_actual_orphan_work_order:${x.id}`);if(Math.abs(web.journal_entries.filter(x=>x.status==='posted').reduce((s,j)=>s+j.lines.reduce((a,l)=>a+l.debit_sar-l.credit_sar,0),0))>0.01)issues.push('posted_journals_unbalanced');if(workforce)for(const x of workforce.factory_labor_allocations)if(!state.manufacturing_orders.some(o=>o.id===x.manufacturing_order_id))issues.push(`factory_labor_orphan_order:${x.id}`);if(!mb.factories.length)issues.push('factory_profile_missing');return issues;}
